<?php get_header();?><main id="main" class="canvas archive-page"><section class="article-head"><p class="eyebrow">JOURNAL / POSTS</p><h1><?php if(is_category())single_cat_title();else echo '文章档案';?></h1><p class="lead">WordPress posts and notes.</p></section><div class="posts" style="margin-top:32px"><?php if(have_posts()):$i=1;while(have_posts()):the_post();?><a class="post-row" href="<?php the_permalink();?>"><span class="code">LOG-<?php echo str_pad((string)$i,3,'0',STR_PAD_LEFT);?></span><span class="post-title"><?php the_title();?></span><span class="meta"><?php $c=get_the_category();echo esc_html($c?$c[0]->name:'Uncategorized');?></span><time class="date"><?php echo esc_html(get_the_date('Y.m.d'));?></time><i class="arrow">↗</i></a><?php $i++;endwhile;else:?><div class="empty">暂无文章。</div><?php endif;?></div></main><?php get_footer();?>